async function auth(e:React.FormEvent<HTMLFormElement>){e.preventDefault();setBusy(true);setAuthError('');const b=Object.fromEntries(new FormData(e.currentTarget));try{await api('auth/'+(reset?'reset':authMode),'POST',{...b,token:reset,demo:b.demo==='on'});if(authMode==='forgot'){toast.success('Если адрес зарегистрирован, письмо отправлено.')}else if(reset){setReset('');history.replaceState({},'',location.pathname);toast.success('Пароль изменён. Войдите в аккаунт.')}else{await refresh()}}catch(e:any){setAuthError(e.message)}finally{setBusy(false)}}
if(loading)return <div className="loading-screen"><LoaderCircle className="spin"/><span>Загружаем рабочее пространство…</span></div>;
if(!data)return <div className="auth-page"><div className="auth-aside"><div className="brand"><span className="brand-mark"><Check/></span>StaffTrack<span>.</span></div><div className="auth-story"><span className="eyebrow">КОМАНДА. ЗАДАЧИ. РЕЗУЛЬТАТ.</span><h1>Большие результаты<br/>начинаются<br/>с маленьких задач.</h1><p>Держите работу в фокусе.<br/>Отмечайте достижения.<br/>Двигайтесь вперёд вместе.</p><div className="auth-feature"><CheckCheck/><span>Понятные задачи и прозрачные сроки</span></div><div className="auth-feature"><Star/><span>Баллы за работу, которая имеет значение</span></div></div><small>StaffTrack · Пространство вашей команды</small></div><div className="auth-main"><form className="auth-card" onSubmit={auth}><span className="eyebrow">ДОБРО ПОЖАЛОВАТЬ</span><h2>{reset?'Новый пароль':authMode==='register'?'Создайте свою команду':authMode==='forgot'?'Восстановление доступа':'Рады видеть вас снова'}</h2><p>{authMode==='register'?'Начните с компании и пригласите сотрудников.':'Всё для работы вашей команды в одном месте.'}</p>{authMode==='register'&&<><Field label="Название компании"><input name="company" required placeholder="Например, Студия 24" maxLength={120}/></Field><Field label="Ваше имя"><input name="name" required autoComplete="name" placeholder="Имя и фамилия" maxLength={120}/></Field></>}{!reset&&<Field label="Email"><input name="email" type="email" required autoComplete="email" placeholder="you@company.ru"/></Field>}{(reset||authMode!=='forgot')&&<Field label="Пароль"><input name="password" type="password" required minLength={authMode==='login'?1:8} maxLength={128} autoComplete={authMode==='login'?'current-password':'new-password'} placeholder="Введите пароль"/></Field>}{authMode==='register'&&<label className="check-line"><Checkbox name="demo" defaultChecked/><span>Добавить демонстрационные задачи и команду</span></label>}{authError&&<div className="form-error" role="alert">{authError}</div>}{loadError&&<div className="form-error" role="alert">{loadError}</div>}<button className="btn primary full" disabled={busy}>{busy?<LoaderCircle className="spin" size={18}/>:reset?'Изменить пароль':authMode==='register'?'Создать компанию':authMode==='forgot'?'Отправить ссылку':'Войти в пространство'}</button>{!reset&&<div className="auth-links">{authMode==='login'?<>{!local&&<button type="button" onClick={()=>{setAuthMode('forgot');setAuthError('')}}>Забыли пароль?</button>}<span>Нет аккаунта? <button type="button" onClick={()=>{setAuthMode('register');setAuthError('')}}>Создать компанию</button></span></>:<button type="button" onClick={()=>{setAuthMode('login');setAuthError('')}}>Вернуться ко входу</button>}</div>}<div className="secure-caption"><ShieldCheck size={16}/>{local?'Автономная версия: данные хранятся в этом браузере. Очистка данных сайта удалит их.':'Ваши данные доступны только вашей команде'}</div></form></div><Toaster position="bottom-right" richColors/></div>;
const employee=data.me.role==='employee',isAdmin=data.me.role==='admin',tasks=data.tasks as Row[],users=data.users as Row[],staff=users.filter(u=>u.role==='employee'),active=tasks.filter(t=>t.status!=='done'),done=tasks.filter(t=>t.status==='done'),late=tasks.filter(t=>t.overdue),review=tasks.filter(t=>t.status==='review'),todayKey=new Date().toLocaleDateString('ru-RU'),today=tasks.filter(t=>new Date(t.deadline).toLocaleDateString('ru-RU')===todayKey&&t.status!=='done');
const titles:Row={dashboard:employee?'Мой рабочий день':'Обзор команды',tasks:employee?'Мои задачи':'Задачи',users:'Сотрудники',rating:'Рейтинг команды',rewards:'Награды',points:'История баллов',analytics:'Аналитика',settings:'Настройки',profile:'Мой профиль'};
const monthKey=new Date().getFullYear()+'-'+String(new Date().getMonth()+1).padStart(2,'0'); const monthTasks=tasks.filter(t=>t.created_at.slice(0,7)===monthKey||t.approved_at?.slice(0,7)===monthKey), monthDone=tasks.filter(t=>t.status==='done'&&t.approved_at?.slice(0,7)===monthKey);
const unread=data.notifications.filter((n:Row)=>!n.read).length;
const filtered=tasks.filter(t=>(!filter.search||t.title.toLowerCase().includes(filter.search.toLowerCase()))&&(filter.employee==='all'||assignedTo(t,filter.employee))&&(filter.department==='all'||(t.assignees||[{department:t.department}]).some((a:Row)=>a.department===filter.department))&&(filter.priority==='all'||t.priority===filter.priority)&&(filter.status==='all'||(filter.status==='overdue'?t.overdue:t.status===filter.status))&&(taskTab==='all'||(taskTab==='active'?t.status!=='done':taskTab==='overdue'?t.overdue:t.status===taskTab))&&(filter.deadline==='all'||(filter.deadline==='today'?new Date(t.deadline).toLocaleDateString('ru-RU')===todayKey:new Date(t.deadline).getTime()<Date.now()+7*86400000&&t.status!=='done')));
function taskTable(rows:Row[]){return rows.length?<Table className="task-table"><TableHeader><TableRow><TableHead>Задача</TableHead>{!employee&&<TableHead>Исполнитель</TableHead>}<TableHead>Статус</TableHead><TableHead>Срок</TableHead><TableHead>Баллы</TableHead><TableHead><span className="sr-only">Открыть</span></TableHead></TableRow></TableHeader><TableBody>{rows.map(t=><TableRow key={t.id}><TableCell><button className="task-title" onClick={()=>openTask(t)}><span className={'task-check '+(t.status==='done'?'checked':'')}>{t.status==='done'&&<Check size={12}/>}</span><div><strong>{t.title}</strong><small className={'priority '+t.priority}>{t.priority==='urgent'?<Flame size={12}/>:<span className="priority-bars">▥</span>}{priorities[t.priority]} приоритет</small></div></button></TableCell>{!employee&&<TableCell><span className="person"><Avatar name={t.assignee_name}/>{t.assignee_name}</span></TableCell>}<TableCell><Status task={t}/></TableCell><TableCell><span className={t.overdue?'late-date':'due-date'}><CalendarDays size={14}/>{date(t.deadline)}</span></TableCell><TableCell><span className="points"><Star size={14}/>{t.points}</span></TableCell><TableCell><button className="icon-btn" aria-label={'Открыть '+t.title} onClick={()=>openTask(t)}><ChevronRight size={17}/></button></TableCell></TableRow>)}</TableBody></Table>:<Empty title="Задач пока нет" body="Создайте задачу или измените фильтры."/>}
